-- Seed basis data Sakka Base (SKENARIO B: User = Pelanggan)
-- AUTO-GENERATED oleh scripts/export_mysql.py — jangan edit manual.
-- PERHATIAN: skrip ini MENGHAPUS tabel lama lalu membuat & mengisi ulang.
SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `model_status`;   -- tabel sisa skema lama (duplikat model_log)
DROP TABLE IF EXISTS `model_log`;
DROP TABLE IF EXISTS `recommendations`;
DROP TABLE IF EXISTS `order_details`;
DROP TABLE IF EXISTS `orders`;
DROP TABLE IF EXISTS `menu_items`;
DROP TABLE IF EXISTS `users`;

CREATE TABLE `users` (
  `id` INT(11) NOT NULL AUTO_INCREMENT,
  `nama_lengkap` VARCHAR(100) NOT NULL,
  `username` VARCHAR(50) NOT NULL,
  `password` VARCHAR(255) NOT NULL,
  `role` ENUM('admin','user') NOT NULL DEFAULT 'user',
  `source` ENUM('historical','registered') NOT NULL DEFAULT 'historical',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `menu_items` (
  `id` INT(11) NOT NULL AUTO_INCREMENT,
  `item_id` VARCHAR(100) NOT NULL,
  `nama_menu` VARCHAR(150) NOT NULL,
  `kategori` VARCHAR(100) DEFAULT NULL,
  `price` INT DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), KEY `item_id` (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `orders` (
  `id` INT(11) NOT NULL AUTO_INCREMENT,
  `user_id` INT(11) DEFAULT NULL,
  `total` INT DEFAULT 0,
  `tanggal` DATE DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), KEY `user_id` (`user_id`),
  CONSTRAINT `fk_orders_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `order_details` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `order_id` INT NOT NULL,
  `menu_item_id` INT NOT NULL,
  `qty` TINYINT DEFAULT 1,
  `price` INT DEFAULT 0,
  PRIMARY KEY (`id`), KEY `order_id` (`order_id`), KEY `menu_item_id` (`menu_item_id`),
  CONSTRAINT `fk_od_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`),
  CONSTRAINT `fk_od_menu` FOREIGN KEY (`menu_item_id`) REFERENCES `menu_items` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `recommendations` (
  `id` INT(11) NOT NULL AUTO_INCREMENT,
  `user_id` INT(11) NOT NULL,
  `menu_item_id` INT(11) NOT NULL,
  `rank` TINYINT(4) NOT NULL,
  `score` FLOAT NOT NULL,
  `generated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), KEY `user_id` (`user_id`), KEY `menu_item_id` (`menu_item_id`),
  CONSTRAINT `fk_rec_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_rec_menu` FOREIGN KEY (`menu_item_id`) REFERENCES `menu_items` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `model_log` (
  `id` INT(11) NOT NULL AUTO_INCREMENT,
  `status` ENUM('training','ready','error') NOT NULL DEFAULT 'ready',
  `model_path` VARCHAR(255) DEFAULT NULL,
  `hr_at_10` FLOAT DEFAULT NULL,
  `ndcg_at_10` FLOAT DEFAULT NULL,
  `trained_at` DATETIME DEFAULT NULL,
  `error_log` TEXT,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;






-- Isi harga tiap baris pesanan dari harga menunya, lalu hitung total per pesanan.
UPDATE `order_details` od
JOIN `menu_items` mi ON mi.id = od.menu_item_id
SET od.price = mi.price;

UPDATE `orders` o
SET o.total = (
  SELECT COALESCE(SUM(od.price * od.qty), 0)
  FROM `order_details` od
  WHERE od.order_id = o.id
);

SET FOREIGN_KEY_CHECKS = 1;